import{_ as r,a0 as u,w as s,s as i,I as l,x as o,a1 as p,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"我买了一台 Linux 笔记本 | LCTT x X-CMD","titleTemplate":false,"description":"我买了一台 Linux 笔记本 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我买了一台 Linux 笔记本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我买了一台 Linux 笔记本 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190719 Buying a Linux-ready laptop","title":"我买了一台 Linux 笔记本","tag":"201910","desc":""},"relativePath":"201910/20190719 Buying a Linux-ready laptop.md","filePath":"[post].md"}'),a={name:"201910/20190719 Buying a Linux-ready laptop.md"};function x(m,t,f,T,L,C){const e=u("Link");return s(),i("div",null,[t[32]||(t[32]=l("h1",{id:"我买了一台-linux-笔记本",tabindex:"-1"},[o("我买了一台 Linux 笔记本 "),l("a",{class:"header-anchor",href:"#我买了一台-linux-笔记本","aria-label":"Permalink to “我买了一台 Linux 笔记本”"},"​")],-1)),t[33]||(t[33]=l("blockquote",null,[l("p",null,"Tuxedo 让买一台开箱即用的 Linux 笔记本变得容易。")],-1)),t[34]||(t[34]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/08/133924vnmbklqh5jkshkmj.jpg",alt:""})],-1)),l("p",null,[t[3]||(t[3]=o("最近，我开始使用我买的 Linux 笔记本计算机 Tuxedo Book BC1507。十年前，如果有人告诉我，十年后我可以从 ",-1)),p(e,{href:"https://system76.com/"},{default:n(()=>[...t[0]||(t[0]=[o("System76",-1)])]),_:1}),t[4]||(t[4]=o("、",-1)),p(e,{href:"https://slimbook.es/en/"},{default:n(()=>[...t[1]||(t[1]=[o("Slimbook",-1)])]),_:1}),t[5]||(t[5]=o(" 和 ",-1)),p(e,{href:"https://www.tuxedocomputers.com/"},{default:n(()=>[...t[2]||(t[2]=[o("Tuxedo",-1)])]),_:1}),t[6]||(t[6]=o(" 等公司购买到高质量的“企鹅就绪”的笔记本电脑。我可能会发笑。好吧，现在我也在笑，但是很开心！",-1))]),l("p",null,[t[9]||(t[9]=o("除了为免费/自由开源软件（FLOSS）设计计算机之外，这三家公司最近",-1)),p(e,{href:"https://www.tuxedocomputers.com/en/Infos/News/Tuxedo-Computers-stands-for-Free-Software-and-Security-.tuxedo"},{default:n(()=>[...t[7]||(t[7]=[o("宣布",-1)])]),_:1}),t[10]||(t[10]=o("都试图通过切换到",-1)),p(e,{href:"https://coreboot.org/"},{default:n(()=>[...t[8]||(t[8]=[o("Coreboot",-1)])]),_:1}),t[11]||(t[11]=o("来消除专有的 BIOS 软件。",-1))]),t[35]||(t[35]=d('<h3 id="买一台" tabindex="-1">买一台 <a class="header-anchor" href="#买一台" aria-label="Permalink to “买一台”">​</a></h3><p>Tuxedo Computers 是一家德国公司，生产支持 Linux 的笔记本电脑。实际上，如果你要使用其他的操作系统，则它的价格会更高。</p><p>购买他们的计算机非常容易。Tuxedo 提供了许多付款方式：不仅包括信用卡，而且还包括 PayPal 甚至银行转帐（LCTT 译注：我们需要支付宝和微信支付……此外，要国际配送，还需要支付运输费和清关费用等）。只需在 Tuxedo 的网页上填写银行转帐表格，公司就会给你发送银行信息。</p><p>Tuxedo 可以按需构建每台计算机，只需选择基本模型并浏览下拉菜单以选择不同的组件，即可轻松准确地选择所需内容。页面上有很多信息可以指导你进行购买。</p><p>如果你选择的 Linux 发行版与推荐的发行版不同，则 Tuxedo 会进行“网络安装”，因此请准备好网络电缆以完成安装，也可以将你首选的镜像文件刻录到 USB 盘上。我通过外部 DVD 阅读器来安装刻录了 openSUSE Leap 15.1 安装程序的 DVD，但是你可用你自己的方式。</p><p>我选择的型号最多可以容纳两个磁盘：一个 SSD，另一个可以是 SSD 或常规硬盘。由于已经超出了我的预算，因此我决定选择传统的 1TB 磁盘并将 RAM 增加到 16GB。该处理器是具有四个内核的第八代 i5。我选择了背光西班牙语键盘、1920×1080/96dpi 屏幕和 SD 卡读卡器。总而言之，这是一个很棒的系统。</p><p>如果你对默认的英语或德语键盘感觉满意，甚至可以要求在 Meta 键上印上一个企鹅图标！我需要的西班牙语键盘则不提供此选项。</p><h3 id="收货并开箱使用" tabindex="-1">收货并开箱使用 <a class="header-anchor" href="#收货并开箱使用" aria-label="Permalink to “收货并开箱使用”">​</a></h3><p>付款完成后仅六个工作日，完好包装的计算机就十分安全地到达了我家。打开计算机包装并解锁电池后，我准备好开始浪了。</p><p><img src="https://opensource.com/sites/default/files/uploads/tuxedo-600_0.jpg" alt="Tuxedo Book BC1507" title="Tuxedo Book BC1507"></p><p><em>我的（物理）桌面上的新玩具。</em></p><p>该电脑的设计确实很棒，而且感觉扎实。即使此型号的外壳不是铝制的（LCTT 译注：他们有更好看的铝制外壳的型号），也可以保持凉爽。风扇真的很安静，气流像许多其他笔记本电脑一样导向后边缘，而不是流向侧面。电池可提供数小时的续航时间。BIOS 中的一个名为 FlexiCharger 的选项会在达到一定百分比后停止为电池充电，因此在插入电源长时间工作时，无需卸下电池。</p><p>键盘真的很舒适，而且非常安静。甚至触摸板按键也很安静！另外，你可以轻松调整背光键盘上的光强度。</p><p>最后，很容易访问笔记本电脑中的每个组件，因此可以毫无问题地对计算机进行更新或维修。Tuxedo 甚至送了几个备用螺丝！</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>经过一个月的频繁使用，我对该系统感到非常满意。它完全满足了我的要求，并且一切都很完美。</p><p>因为它们通常是高端系统，所以包含 Linux 的计算机往往比较昂贵。如果你将 Tuxedo 或 Slimbook 电脑的价格与更知名品牌的类似规格的价格进行比较，价格相差无几。如果你想要一台使用自由软件的强大系统，请毫不犹豫地支持这些公司：他们所提供的物有所值。</p><p>请在评论中让我们知道你在 Tuxedo 和其他“企鹅友好”公司的经历。</p><hr>',19)),l("p",null,[t[14]||(t[14]=o("本文基于 Ricardo 的博客 ",-1)),p(e,{href:"https://frommindtotype.wordpress.com/"},{default:n(()=>[...t[12]||(t[12]=[o("From Mind to Type",-1)])]),_:1}),t[15]||(t[15]=o(" 上发表的“ ",-1)),p(e,{href:"https://frommindtotype.wordpress.com/2019/06/17/my-new-penguin-ready-laptop-tuxedo-book-bc1507/"},{default:n(()=>[...t[13]||(t[13]=[o("我的新企鹅笔记本电脑：Tuxedo-Book-BC1507",-1)])]),_:1}),t[16]||(t[16]=o("”。",-1))]),t[36]||(t[36]=l("hr",null,null,-1)),l("p",null,[t[18]||(t[18]=o("via: ",-1)),p(e,{href:"https://opensource.com/article/19/7/linux-laptop"},{default:n(()=>[...t[17]||(t[17]=[o("https://opensource.com/article/19/7/linux-laptop",-1)])]),_:1})]),l("p",null,[t[23]||(t[23]=o("作者：",-1)),p(e,{href:"https://opensource.com/users/rgb-es"},{default:n(()=>[...t[19]||(t[19]=[o("Ricardo Berlasso",-1)])]),_:1}),t[24]||(t[24]=o(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[20]||(t[20]=[o("lujun9972",-1)])]),_:1}),t[25]||(t[25]=o(" 译者：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[o("wxy",-1)])]),_:1}),t[26]||(t[26]=o(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[22]||(t[22]=[o("wxy",-1)])]),_:1})]),l("p",null,[t[29]||(t[29]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[27]||(t[27]=[o("LCTT",-1)])]),_:1}),t[30]||(t[30]=o(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...t[28]||(t[28]=[o("Linux中国",-1)])]),_:1}),t[31]||(t[31]=o(" 荣誉推出",-1))])])}const y=r(a,[["render",x]]);export{S as __pageData,y as default};
